import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{B as i,F as a,H as o,I as s,L as c,R as l,V as u,z as d}from"./chunks/assets.8isJ-IUK.js";var f=JSON.parse(`{"title":"Special fields","description":"","frontmatter":{},"headers":[],"relativePath":"special-fields.md","filePath":"special-fields.md"}`),p={name:`special-fields.md`},m=o+` 1x, `+u+` 2x`,h=i+` 1x, `+d+` 2x`,g=l+` 1x, `+c+` 2x`,_=s+` 1x, `+a+` 2x`;function v(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="special-fields" tabindex="-1">Special fields <a class="header-anchor" href="#special-fields" aria-label="Permalink to “Special fields”">​</a></h1><p>In addition to the fields that you create in the <a href="/fields.html">fields section</a>, the module provides a number of other fields that you can use in your formula as well as in your php codes.</p><p>To access these extra fields, click the show more button in any formula panel</p><p><img src="/webp/extra-fields.png-90-1788222277552.webp" srcset="`+m+`" alt="Extra fields" title="" width="1792" height="1284" loading="lazy" style="width:896px;"></p><h2 id="prestashop-fields" tabindex="-1">PrestaShop fields <a class="header-anchor" href="#prestashop-fields" aria-label="Permalink to “PrestaShop fields”">​</a></h2><h3 id="product-price" tabindex="-1">product_price <a class="header-anchor" href="#product-price" aria-label="Permalink to “product_price”">​</a></h3><p>The original product price without taxes and without reductions</p><p>This price may contain the current combination price impact</p><p><img src="/webp/product-price.jpg-90-1788222277570.webp" srcset="`+h+`" alt="Product price" title="" width="1320" height="574" loading="lazy" style="width:660px;"></p><h3 id="product-weight" tabindex="-1">product_weight <a class="header-anchor" href="#product-weight" aria-label="Permalink to “product_weight”">​</a></h3><p>The original product weight including the selected combination weight impact</p><p><img src="/webp/product-weight.jpg-90-1788222277570.webp" srcset="`+g+`" alt="Product weight" title="" width="1362" height="454" loading="lazy" style="width:681px;"></p><h3 id="quantity" tabindex="-1">quantity <a class="header-anchor" href="#quantity" aria-label="Permalink to “quantity”">​</a></h3><p>The quantity selected by the customer</p><p><img src="/webp/quantity-input.jpg-90-1788222277573.webp" srcset="`+_+`" alt="Quantity input" title="" width="546" height="144" loading="lazy" style="width:273px;"></p><h2 id="product-attributes" tabindex="-1">Product attributes <a class="header-anchor" href="#product-attributes" aria-label="Permalink to “Product attributes”">​</a></h2><p>This section will display the list of the attributes that are used by the current product combinations</p><p>The value of each field will contain the current value of the attribute that is selected by the customer.</p><p>The attribute names are prefixed by <code>attribute_</code> and are transformed to lowercase and any accented characters or symbols are removed in order to comply with <a href="/fields.html">fields names</a> rules.</p><h2 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to “Databases”">​</a></h2><p>This section will be displayed if you have csv files in the <code>databases</code> data folder.<br> Check the <a href="/formula-functions.html#the-grid-function">Grid function</a> documentation to learn more</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to “Features”">​</a></h2><p>Similar to the attribute names section, this section will display product features. The value of each field will contain the value of the corresponding product feature.</p><h2 id="hidden-fields" tabindex="-1">Hidden fields <a class="header-anchor" href="#hidden-fields" aria-label="Permalink to “Hidden fields”">​</a></h2><h3 id="changed" tabindex="-1">changed <a class="header-anchor" href="#changed" aria-label="Permalink to “changed”">​</a></h3><p>The module provides a field with the name <code>changed</code> which holds the name of the field that the customer changed in order to trigger the calculation</p><p>This field is also available in <a href="/php-calculation.html#other-available-variables">php</a>, via the variable <code>$changed</code></p><p>It&#39;s useful when you want to change the value of a field only when a specific field is changed.</p><p>Example: If the width is changed, set the height to double the width</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[height] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[changed]&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [width] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [height] )</span></span></code></pre></div><h3 id="step" tabindex="-1">step <a class="header-anchor" href="#step" aria-label="Permalink to “step”">​</a></h3><p>You can create a field called step to use it to control the selected step.</p><p>Make sure to give your <a href="/steps.html">steps</a> a unique name each.</p><p>Example: If the material picked is wood, then jump to step 3 called color, otherwise don&#39;t change the step</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[step] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> IF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[changed]&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;material&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[material]&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;wood&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[step]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div>`,35)]])}var y=e(p,[[`render`,v]]);export{f as __pageData,y as default};